import{a as e,i as t,r as n,t as r}from"./app-C9b2Di87.js";var i=JSON.parse(`{"path":"/med_pulse/","title":"《天宫医疗》","lang":"zh-CN","frontmatter":{},"git":{},"filePathRelative":"med_pulse/index.md"}`),a={name:`index.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="《天宫医疗》" tabindex="-1"><a class="header-anchor" href="#《天宫医疗》"><span>《天宫医疗》</span></a></h1><h2 id="项目背景" tabindex="-1"><a class="header-anchor" href="#项目背景"><span>项目背景：</span></a></h2><p>想象你是一家三甲医院的信息科负责人。每天，门诊医生要查药品说明书、检验科要解读化验单、药剂科要检查处方冲突、患者打电话来问 &quot;我这个症状该挂什么科&quot;。这些信息散落在不同系统里 —— 药品数据在 HIS 系统、疾病知识在医学百科、检查报告在 PACS 系统、患者历史在电子病历里。</p><p>我们要构建一个医疗智能体，把这些数据统一起来，让 AI 能够跨系统回答问题。</p><h1 id="技术角度" tabindex="-1"><a class="header-anchor" href="#技术角度"><span>技术角度</span></a></h1><p>从技术角度，医疗是ai落地最有价值，也是最有挑战性的领域之一，它天然包含了AI应用几乎所有技术难点</p><p>业务痛点 对应技术挑战 患者描述模糊，需多轮引导 多轮对话 + 短期记忆 报告 / 影像需要理解图文 视觉语言模型（VLM） 医学知识专业且分散 RAG 知识库检索 药物关系复杂，存在多跳依赖 知识图谱 + 图推理 运营人员不会写 SQL NL2SQL Agent 患者历史记录需跨会话记忆 长期记忆（向量数据库）</p><p>用医疗场景学 AI 框架，每一个技术点都有真实的业务动机，不是为了用技术而用技术。</p><h1 id="核心用户角色" tabindex="-1"><a class="header-anchor" href="#核心用户角色"><span>核心用户角色</span></a></h1><p>项目包含三类用户进行使用：</p><ol><li>患者 / 普通用户：症状自查、报告解读、用药咨询、健康科普</li><li>医生 / 临床医生：辅助诊断、药物交互检测、影像分析、文献检索</li><li>医院管理 / 运营：数据查询、运营统计、患者画像、系统监控</li></ol><p>中转站：https://www.vibeapi.cn/console/token</p>`,12)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};